59	      }
60	
61	      // Prevent the autosave unmount flush from restoring the saved draft.
62	      discardDraft();
63	
64	      const invalidationPromises = [
65	        queryClient.invalidateQueries({ queryKey: memoKeys.lists() }),
66	        queryClient.invalidateQueries({ queryKey: userKeys.stats() }),
67	      ];
68	      if (memoName) {
69	        invalidationPromises.push(queryClient.invalidateQueries({ queryKey: memoKeys.detail(memoName) }));
70	      }
71	      if (parentMemoName) {
72	        invalidationPromises.push(queryClient.invalidateQueries({ queryKey: memoKeys.comments(parentMemoName) }));
73	      }
74	      await Promise.all(invalidationPromises);
